function AddRightHeaderLogo (url)
{

    $(".cf-page__header").after("<div class='cf-page__header, logo_right' role='banner'>")
}

function setlogo() {
    var head = document.getElementsByTagName('head')[0];
    var link = document.createElement("link");
    link.rel = "shortcut icon";
    link.href = "/isa/PYAMLMFAKKOYIBEYNHKRJRBIMIEALXOH/logos/SRC_favicon.svg";
    head.appendChild(link);
}
if (window.attachEvent) {
    window.attachEvent("onload", setlogo);
} else if (window.addEventListener) {
    window.addEventListener("load", setlogo, false);
}


function validateData(){
    var result = Confirmit.page.validate();
    var errors = result.questionValidationResults.length;
    if(errors == 0){
        saveData();
    }
}

function clearData() {
    var responses = Confirmit.page.questions;
    for (var i = 0; i < responses.length; i++) {
        var question = responses[i];
        if(Object.keys(question.formValues).length > 0){
            question.clearValues();
        }
    }
}

function saveData() {

    var url = document.URL;
    var params = Confirmit.page.serverVariables._fields;

    var responses = Confirmit.page.formValues;
    for (var i = 0; i < responses.length; i++) {
        var name = responses[i]["name"];
        var value = responses[i]["value"];
        params[name] = value;
    }

    var xhr = new XMLHttpRequest();
    xhr.open("POST", url, true);
    xhr.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
    xhr.onreadystatechange = function () {
        if (xhr.readyState === 4 && xhr.status === 200) {
            document.getElementById("save-btn").innerText = "Saved!";
            setTimeout(function () {
                document.getElementById("save-btn").innerText = "Save and close";
            }, 2000);
        }
    };
    var queryString = new URLSearchParams(params).toString();
    xhr.send(queryString);
}



function categorical_hideDKREF() {
    var mode = Number('^f("mode").get()^');
    if (mode == 1) {
        
        //if page question
        if($('.cf-page__question-list').length>0)
        {
            $('.cf-page__question-list .cf-question').each(function(){
                    var exclusivecodesLength_page = $(this).find('.exclusivecodes').length
                console.log(exclusivecodesLength_page)
                if ($(this).find('.cf-radio--selected').length == 0 && $(this).find('.cf-checkbox--selected').length == 0 && $('.cf-error-list__item').length == 0 && exclusivecodesLength_page > 0) {
                $(this).find('.cf-list__item').slice(-1 * exclusivecodesLength_page).hide()
                }
            })
           
            $('.cf-navigation').on('click', function () {
                 if ($('.cf-error-list__item').length > 0) {
    
                    $(".cf-list .cf-list__item").show()
                    $('.cf-error-list__item').each(function() {
                        if ($(this).text().trim().includes('Please select an answer')) { console.log($(this).text())
                        $(this).text('You have not provided a response. Is that because you’re not sure, or you would prefer not to answer?');
                        }
                        });
                }


            })
        }
        else
        {
        var exclusivecodesLength = $('.exclusivecodes').length
        if ($('.cf-radio--selected').length == 0 && $('.cf-checkbox--selected').length == 0 && $('.cf-error-list__item').length == 0 && exclusivecodesLength > 0) {
            $(".cf-list .cf-list__item").slice(-1 * exclusivecodesLength).hide()
        }
        $('.cf-navigation').on('click', function () {
            var exclusivecodesLength = $('.exclusivecodes').length
            if ($('.cf-error-list__item').length > 0) {
                $(".cf-list .cf-list__item").slice(-1 * exclusivecodesLength).show()
            }


        })
        }
    }
}
function hideDKREF_grid(hid_lastN, qType = 'default') {
    var mode ='^f("mode").get()^';
    if (mode == 1) {
    $('.cf-desktop-grid  table tr').add('.cf-desktop-multi-grid table tr').add('.cf-mobile-grid-layout .cf-list').add('.cf-carousel__content-item').add('.cf-accordion-grid-answer').add('.cf-question.cf-question--multi').each(function () {
            if (qType.toLowerCase() == 'default') {
                if ($(".cf-error-list__item").length == 0 && $('.cf-radio-answer--selected').length == 0&&$('.cf-checkbox--selected').length==0) {
                    if ($(this).hasClass('cf-table-layout__row--head')) {
                        $(this).find('th').slice(-1 * hid_lastN).hide();
                    }
                    else {
                        $(this).find('td').slice(-1 * hid_lastN).hide();

                    }
                    //Mobile
                    $(this).find('.cf-list__item').slice(-1 * hid_lastN).hide();
                }
            }
            else if (qType.toLowerCase() == 'carousel') {
                $(this).find('.cf-list__item').slice(-1 * hid_lastN).hide();

            }
            else if (qType.toLowerCase() == 'accordion') {
                if ($(".cf-error-list__item").length == 0 && ($('.cf-radio-answer--selected').length == 0 || $('.cf-checkbox--selected').length==0)){
                //grid single
                $(this).find('.cf-accordion-grid-answer__scales .cf-list__item').slice(-1 * hid_lastN).hide();
                //grid multi
             
                $(this).find('.cf-question__content .cf-list .cf-list__item').slice(-1 * hid_lastN).hide();
                }
            }


        })
    }
    $('.cf-navigation').on('click', function (hid_lastN) {

        if ($('.cf-error-list__item').length > 0) {
            $('.cf-desktop-grid  table tr').add('.cf-mobile-grid-layout .cf-list').add('.cf-desktop-multi-grid table tr').each(function (hid_lastN) {
                $(this).find('td').slice(-1 * hid_lastN).show();

                $(this).find('th').slice(-1 * hid_lastN).show();
                //Mobile
                $(this).find('.cf-list__item').slice(-1 * hid_lastN).show();

            })

            //carousel
            $('.cf-carousel__content-item--current').find('.cf-list__item').slice(-1 * hid_lastN).show();
            //accordion
            $('.cf-collapsing-panel--open').find('.cf-list__item').slice(-1 * hid_lastN).show();
            if($('.cf-question.cf-question--multi'))
            {
                $('.cf-question.cf-question--multi').each(function(){
                    $(this).find('.cf-list__item').slice(-1 * hid_lastN).show();
                                    })
                
              

            }

            //error message
                                $('.cf-error-list__item').each(function() {
                        if ($(this).text().trim().includes('Please select an answer')) { 
                        $(this).text('You have not provided a response. Is that because you’re not sure, or you would prefer not to answer?');
                        }
                        });

        }


    })

}


function codeOrder_grid(placeholder, qtype = '') {
    var order = Number('^ f("s_order").get() ^')
    if (order == "2") {
        if (qtype.toLowerCase()=='carousel') {

            $(".cf-carousel__content .cf-carousel__content-item").each((index, elem) => {

                let listContainer = $(elem).find(".cf-list");
                let answerBtn = listContainer.find('.cf-list__item');
                var exclusive_item_count = listContainer.find(".exclusive_item_grid").length;
                reverse_grid_s_order(listContainer, answerBtn, exclusive_item_count)
            })

        }
        else if(qtype.toLowerCase()=='accordion')
        {
        //revered order
         
            $(".cf-list").css("flex-direction","column-reverse")
            if($('.exclusive_item_grid').length>0)
            {   
                $(".cf-accordion-grid-answer").each(function(){

                    var exclusivecodesLength = $(this).find('.exclusive_item_grid').length
                    for (let i = 0; i < exclusivecodesLength; i++) {
                        $(this).find('.cf-list__item').eq(-1 * (i + 1)).css('order', -1 * (exclusivecodesLength) + i)
                    }

                })
            

            }
        }
        else {
            //Normal table grid
            let $tr = $('.cf-desktop-grid .cf-table-layout__row--head');
            let $thElements = $tr.children('th');
            var exclusive_item_count = $(".cf-desktop-grid .exclusive_item_grid").length;
            reverse_grid_s_order($tr, $thElements, exclusive_item_count)
            $('.cf-desktop-grid .cf-table-layout__body tr').each(function () {
                let exclusive_item_count = $(".cf-desktop-grid .exclusive_item_grid").length;
                let $parent = $(this);
                let $elemtToReverse = $(this).find('td');
                reverse_grid_s_order($parent, $elemtToReverse, exclusive_item_count)
            })

            //mobile
            //revered order
            let answerLists = $(".cf-mobile-grid-layout .cf-mobile-grid-layout__answer-content .cf-list")
            answerLists.css("flex-direction", "column-reverse")

            let answerListParent = $(".cf-mobile-grid-layout .cf-mobile-grid-layout__answer-content")
            answerListParent.each(function () {
                let exclusive_item_count = $(this).find('.exclusive_item_grid').length

                for (var i = 0; i < exclusive_item_count; i++) {
                    $(this).find('.cf-list__item').eq(-1 * (i + 1)).css('order', -1 * exclusive_item_count + i)

                }
            })



        }

    }
}

function categorical_s_order() {
    var order ='^f("s_order").get()^';
    if (order == 2) {
        //revered order
        $(".cf-list").css("flex-direction", "column-reverse")
        if ($('.exclusivecodes').length > 0) {
            var exclusivecodesLength = $('.exclusivecodes').length
            for (let i = 0; i < exclusivecodesLength; i++) {
                $('.cf-list__item').eq(-1 * (i + 1)).css('order', -1 * (exclusivecodesLength) + i)
            }

        }
    }
}

function reverse_grid_s_order(parent_elem,child_elem,fixitemCount)
{
    let remaining 
    if (fixitemCount > 0) {
    // Separate last two element
     remaining = child_elem.slice(0, fixitemCount*-1); 
    }
    else
    {
     remaining = child_elem
    }
    // Reverse and re-append only the remaining elements
    remaining.toArray().reverse().forEach(th => parent_elem.append(th));
     
    if (fixitemCount>0){
        let lastTwo = child_elem.slice(fixitemCount * -1);
        // Re-append last two elements to preserve their original order
        lastTwo.each((_, th) => parent_elem.append(th));
    }

}


