function captureorder_scale(Q,c) 
{
    f(Q+'_scale_order').set(f(Q+'_'+c).domainValues().toLocaleString());
    //f(CurrentForm()+'_scale_order').set(f(CurrentForm()+'_'+c).domainValues().toLocaleString());
}

function GridFilter(QID, st, arr) {
    var s = set()
    var prec = null;
    if (arr.length == 0) 
    {
        var prec = f(QID).domainValues(); 
    }
    else 
    {
        var prec = arr;
    }
    for (var i = 0; i < prec.length; i++) {
        var code = prec[i];
        if (f(QID).item(code).isect(st).size() > 0) {
            s.add(code);
        }
    }
    return s;
}
// Function to clear multi
// To use  call clearMulti("questionID") from whereever required

function clearMulti(qID) {

    var qans=f(qID).domainValues()

    for (var i=0;i<qans.length;i++)
    {
        var code=qans[i];
        f(qID).item(code).set(null)
    }
}

