if (!f('NL_Seen').toBoolean())
{
    if ((!f('NL_child_first_name').toBoolean() || !f('NL_child_family_name').toBoolean() || !f('NL_child_dob').toBoolean() || !f('NL_child_sex').toBoolean())
    && !f("NL_child_em").any("1")) 
        {
            f("NL_child_em").set("1"); 
            errormessage('23');
        }
        else
        {
            f("NL_child_em").set(null);
        }
}

if (f(CurrentForm()).toBoolean()) 
  {
    var toD = new Date();
	//var fromD = addDays(new Date(),43800); // min is 120 years
	//fromDate.setDate(fromDate.year-120,fromDate.month,fromDate.day);

    //if (f("DOB").toDate() < fromD || f("DOB").toDate() > toD)
      if ( f(CurrentForm()).toDate() > toD)
      {
        errormessage(1);
      }    

    var dob = f(CurrentForm()).toDate();
    var today = new Date();  

    var age = today.getFullYear() - dob.getFullYear();
    var m = today.getMonth() - dob.getMonth();

    if (m < 0 || (m === 0 && today.getDate() < dob.getDate())) {
        age = age -1;
    }
    f('NL_childage').set(age);

   if ((f('NL_childage').toNumber() < (f('child_age').toNumber()-1)) || 
      (f('NL_childage').toNumber() >(f('child_age').toNumber()+1))) 
      {
        errormessage('22');
      }

  }

