if(!IsEmail(f(CurrentForm())))
{
RaiseError();
//SetQuestionErrorMessage(LangIDs.en_gb,"Please provide a valid email address.");
SetQuestionErrorMessage(LangIDs.en,"Please provide a valid email address.");
}

f('EmailCollected').set(f('CAWIEmailAddress').get())
//Request the tempory key
var APIKey = "redacted"
  //Request the tempory key
var requestString =  "https://api.everest.validity.com/api/2.0/validation/addresses/";
requestString=requestString+f('CAWIEmailAddress').get()
var response = Http.Get(requestString,"",{"X-API-Key":APIKey});
var jsonObj = JSON.parse(response);
var resultReturn=JSON.parse(JSON.stringify(jsonObj["results"]))
var resultCategory = JSON.stringify(resultReturn["category"])
f('EmailReturnValues_category').set(resultCategory.toLowerCase().replace(/""/g, ""))
f('EmailReturnText').set(JSON.stringify(resultReturn))

var returnvalueCat=f('EmailReturnValues_category').get()


if( returnvalueCat.includes("email_domain_invalid"))
{

        RaiseError();
    SetQuestionErrorMessage(LangIDs.en,"Domain for email (AFTER '@') does not exist, please double check it");
}
else if(returnvalueCat.includes("email_address_invalid"))
{
        RaiseError();

    SetQuestionErrorMessage(LangIDs.en,"Email address does not exist, please double check your answer");

}
else if(returnvalueCat.includes("email_account_invalid"))
{

            RaiseError();

    SetQuestionErrorMessage(LangIDs.en,"Email account does not exist, please double check your answer");
}
else if(returnvalueCat.includes("accept_all","role_address","disposable"))
{
        RaiseError();

    SetQuestionErrorMessage(LangIDs.en,"Email address is possibly invalid, please double check your answer");

}

