function DisplayCallHistory() {
    //var tries:int=GetCallAttemptCount();
    //var start:int=1;

    //var tries = GetCallAttemptCount();
    var tries = f('total_attempt_count');

  //Response.Write(tries);
    var start = 1;

    if (tries > 10) {
        start = tries - 10;
    }

    if (tries > 1) {
        var string = "";
        string += "<table border=1>";
        string += "<tr>";
        string += "<td>History ID</td>";
        string += "<td>Date/Time</td>";
        string += "<td>Interview Mode</td>";
        string += "<td>Outcome</td>";
        string += "<td>EndQ</td>";
        //string += "<td>Call ID</td>";
        //string += "<td>Date/Time</td>";
        string += "<td>Interviewer</td>";
        //string += "<td>Call Outcome</td>";
        string += "<td>App Date/Time</td>";
        //string += "<td>Contact</td>";
        string += "<td>Comments</td>";
        string += "</tr>";

        for (var i = start; i <= (tries - 1); i++) {
            /*
            var dateAll : String = f('start_date_time',i).get();
            var DateArray : Array = dateAll.split(" ");
            var DateFmt : String = DateArray[0] + " "+DateArray[1] +" "+DateArray[2]+" "+DateArray[3];
            */

            var dateAll = f('start_date_time', i).get();
            //var DateArray = new Array(dateAll.split(" "));
            //var DateFmt = DateArray[0] + " " + DateArray[1] + " " + DateArray[2] + " " + DateArray[3];

            //var datetime=f('start_date_time',i).toBoolean() ? f('start_date_time',i).get() : "&nbsp;";  //DO NOT UNCOMMENT

            /*
            var datetime=DateFmt != null ? DateFmt : " ";

            var interviewer=f('call_inter_name',i).toBoolean() ? f('call_inter_name',i).get() : " ";
            var its=f('contact_extended_status',i).toBoolean() ? f('contact_extended_status',i).valueLabel() : "&nbsp;";

            var AppAll : String = f('call_app_time',i).get();
            var ADateArray : Array = AppAll.split(" ");
            var ADateFmt : String = ADateArray[0] + " "+ADateArray[1] +" "+ADateArray[2]+" "+ADateArray[3];
            var apptime=f('call_app_time',i).toBoolean() ? ADateFmt : "&nbsp;";

            var contactperson=f('call_contact_person',i).toBoolean() ? f('call_contact_person',i).get() : "&nbsp;";
            var comments=f('call_comments',i).toBoolean() ? f('call_comments',i).get() : "&nbsp;" + "</td>";
            */

            if (f('start_date_time',i).toBoolean()) {
                //var datetime=DateFmt != null ? DateFmt : " ";
                var interviewmode = f('interview_mode', i);
                var endQ = f('session_endQ', i);
                var interviewer = f('call_inter_name', i).toBoolean() ? f('call_inter_name', i).get() : " ";
                var its = f('contact_extended_status', i).toBoolean() ? f('contact_extended_status', i).valueLabel() : "&nbsp;";

                var AppAll = f('call_app_time', i).get();
                if (AppAll != null) {
                    var ADateArray = new Array(AppAll.split(" "));
                    var ADateFmt = ADateArray[0] + " "+ADateArray[1] +" "+ADateArray[2]//+" "+ADateArray[3];
                }
                var apptime = f('call_app_time', i).toBoolean() ? ADateFmt : "&nbsp;";

                //var contactperson = f('Call_contact_person', i).toBoolean() ? f('Call_contact_person', i).get() : "&nbsp;";
                var comments = f('call_comments', i).toBoolean() ? f('call_comments', i).get() : "&nbsp;" + "</td>";

                string += "<tr>";
                string += "<td>" + i + "</td>";
                string += "<td>" + dateAll + "</td>";
                string += "<td>" + interviewmode + "</td>";
                string += "<td>" + its + "</td>";
                string += "<td>" + endQ + "</td>";
                //string += "<td>" + dateAll + "</td>";
                string += "<td>" + interviewer + "</td>";
                //string += "<td>" + its + "</td>";
                string += "<td>" + apptime + "</td>";
                //string += "<td>" + contactperson + "</td>";
                string += "<td>" + comments + "</td>";
                string += "</tr>";
            }
        }
        string += "</table>";
    }
    return string;
}

